import {MemoryStorageDriver,type StorageDriver} from '../../web/runtime/storage.ts';
import {DefaultProgressStore} from '../../web/runtime/progress.ts';
import {DefaultCognitiveStore} from '../../web/runtime/cognitive-store.ts';
import {CognitiveController,type CognitiveAuthority} from '../../web/journeys/cognitive-controller.ts';
import {StandardAssessmentEngine,SCORING_VERSION,type AssessmentContract} from '../../web/runtime/assessment.ts';
import {canonicalJson,computeSha256,sameRef} from '../../web/runtime/loader.ts';
import {Core1BTransferJourney,transferDefinitionDigest,type Core1BTransferDefinition} from '../../web/journeys/core1b.ts';
import {CORE1A_ORDERED_ROLES,ANCHOR_LEVELS,type Core1ALessonDefinition} from '../../web/journeys/core1a.ts';
import type {Ref,TaskRef,Session,JourneyKey,WorkArtifact,Response} from '../../web/runtime/types.ts';
export const ref=<T extends Ref['type']>(type:T,id:string,sha256='a'.repeat(64)):Ref<T>=>({type,id,revision:1,sha256});
export const artifact=(id:string,value='working'):WorkArtifact=>({id,kind:'NOTE',version:1,value});
export const firstResponses={a:{kind:'INTEGER',value:'7'},b:{kind:'CONSTRUCTED_RESPONSE',value:'learner reasoning'}} satisfies Record<string,Response>;
export const boundaryResponses={c:{kind:'INTEGER',value:'8'}} satisfies Record<string,Response>;
export const lesson=():Core1ALessonDefinition=>({lessonRef:ref('LESSON','lesson:wave8'),constructionRef:ref('CONSTRUCTION','construction:wave8'),title:'Synthetic teaching',subject:'PHYSICS',topicId:'topic:wave8',depthBadge:'MEDIUM',status:'SYNTHETIC',units:CORE1A_ORDERED_ROLES.map(role=>({role,title:'Unit '+role,summary:'Public summary',bodyText:'Public body',blockRefs:[ref('SOURCE','source:'+role)],evidenceRefs:[ref('WARRANT','warrant:'+role)],...(role==='A6'?{workedExample:{problemPrompt:'Example prompt',fullReasoningSteps:['SECRET_WORKED'],solutionResult:'SECRET_RESULT'}}:{}),...(role==='A7'?{misconception:{wrongIdea:'Wrong path',diagnosticPrompt:'Diagnostic question',repair:'SECRET_REPAIR'}}:{})})),anchors:ANCHOR_LEVELS.map(level=>({level,taskRef:ref('QUESTION','question:'+level),title:level,prompt:'Public anchor prompt',solutionRef:ref('SOLUTION','solution:'+level),solutionSteps:['SECRET_ANCHOR'],warrantRefs:[ref('WARRANT','warrant:'+level)]})),modelConfig:{modelId:'PHYS-MODEL-ENERGY-WELL',modelName:'Potential well',defaultParameters:{x:0},parameterBounds:{x:{min:-.5,max:.5}},qualitativePredictionPrompt:'Predict',predictionOptions:['first','second'],expectedPredictionIndex:1,observationNote:'SECRET_OBSERVATION'},synthesisTaskRef:ref('QUESTION','question:synthesis'),synthesisTaskPrompt:'Distinct synthesis prompt',freshTaskRef:ref('FRESH_TASK','fresh:reserved')});
export async function setupTransfer(driver:StorageDriver=new MemoryStorageDriver(),initialize=true){
 const bytes=new Map<string,Uint8Array>();const asset=async<T extends Ref['type']>(type:T,id:string,text:string)=>{const v=new TextEncoder().encode(text);bytes.set(id,v);return ref(type,id,await computeSha256(v));};
 const origin=ref('LESSON','lesson:transfer:origin'),first:TaskRef=await asset('FRESH_TASK','fresh:task:a','First task bytes'),boundary:TaskRef=await asset('FRESH_TASK','fresh:task:b','REVIEWED_BOUNDARY_STIMULUS');
 const firstRef=await asset('SOLUTION','solution:task:a','REVIEWED_FIRST_REFERENCE'),boundaryRef=await asset('SOLUTION','solution:task:b','REVIEWED_BOUNDARY_REFERENCE');
 const hint1=await asset('ASSET','asset:hint:h1','REVIEWED_HINT_ONE'),hint2=await asset('ASSET','asset:hint:h2','REVIEWED_HINT_TWO');
 const releaseId='release:wave8:synthetic',key:JourneyKey={journeyId:'journey:wave8',taskInstanceId:'instance:wave8',releaseId,task:first};
 const session=(id:string,item:Ref,originRef:Ref|null):Session=>({id,item,releaseId,origin:originRef,mode:'PRACTICE',contentRevision:'r1',deadlineAt:null,returnRoute:null,cursor:7,attemptIds:[],draftId:null});
 const os=session('session:origin',origin,null),as=session('session:first',first,origin),bs=session('session:boundary',boundary,origin);
 if(initialize)for(const x of [os,as,bs])await driver.put('sessions',x.id,x);
 const definition:Core1BTransferDefinition={journeyId:key.journeyId,originRef:origin,freshTaskA:{taskRef:first,title:'Fresh task A',prompt:'Public first prompt',conditions:['Condition A'],solutionRef:firstRef,solutionSteps:['SECRET_EMBEDDED_FIRST'],targetNumeric:{value:99,unit:'m',tolerance:0}},boundaryTaskB:{taskRef:boundary,title:'SECRET_BOUNDARY_TITLE',prompt:'SECRET_BOUNDARY_PROMPT',conditions:['SECRET_BOUNDARY_CONDITION'],solutionRef:boundaryRef,solutionSteps:['SECRET_EMBEDDED_BOUNDARY']},hints:[{level:'H1',assetRef:hint1,text:'SECRET_HINT',guidance:'SECRET_GUIDANCE'},{level:'H2',assetRef:hint2,text:'SECRET_HINT_2',guidance:'SECRET_GUIDANCE_2'}],diagnosticRules:[{code:'move:one',label:'Move one',misconceptionDescription:'SECRET_DIAG',correctiveGuidance:'SECRET_CORRECTIVE'}],qualitativePredictionPrompt:'Prediction prompt',predictionOptions:['UNSURE','Alternative'],expectedPredictionIndex:1,status:'SYNTHETIC'};
 const firstFields={a:'INTEGER' as const,b:'CONSTRUCTED_RESPONSE' as const},boundaryFields={c:'INTEGER' as const};
 const sub=(id:string,t:TaskRef,kind:Response['kind'],value?:string):AssessmentContract=>({id,task_ref:t,response_kind:kind,max_points:1,evaluator:value===undefined?{mode:'REVIEW_PENDING'}:{mode:'AUTOMATIC',canonical_value:value}});
 const contracts:AssessmentContract[]=[{id:'asmt:wave8:a',revision:1,task_ref:first,response_kind:'MULTIPART',max_points:2,evaluator:{mode:'REVIEW_PENDING'},parts:{a:sub('asmt:sub:a',first,'INTEGER','7'),b:sub('asmt:sub:b',first,'CONSTRUCTED_RESPONSE')}},{id:'asmt:wave8:b',revision:1,task_ref:boundary,response_kind:'MULTIPART',max_points:1,evaluator:{mode:'REVIEW_PENDING'},parts:{c:sub('asmt:sub:c',boundary,'INTEGER','8')}}];
 const assessments=await Promise.all(contracts.map(async c=>ref('ASSESSMENT',c.id,await computeSha256(canonicalJson(c)))));
 const engine=new StandardAssessmentEngine(assessments.map((assessment,i)=>({assessment,task:contracts[i].task_ref as TaskRef})));for(let i=0;i<2;i++)await engine.registerContract(contracts[i],assessments[i]);
 const progress=new DefaultProgressStore(driver,async a=>{const i=assessments.findIndex(x=>!!a.assessmentRef&&sameRef(a.assessmentRef,x));return i>=0&&a.releaseId===releaseId&&a.scoringVersion===SCORING_VERSION&&sameRef(a.item,contracts[i].task_ref)&&canonicalJson(a.grade)===canonicalJson(await engine.evaluate(a.response,assessments[i],'PRACTICE',a.item as TaskRef));});
 const store=new DefaultCognitiveStore(driver,progress);
 let enabled=true;const authority:CognitiveAuthority={liveRevision:async()=> 'r1',reviewedContext:async()=>({releaseId,task:first,boundaryTask:boundary,firstReference:firstRef,boundaryReference:boundaryRef,firstFields,boundaryFields,moves:['move:one','move:two']}),allowed:async(_j,_s,cap,asset)=>enabled&&(cap==='H1'&&sameRef(asset,hint1)||cap==='H2'&&sameRef(asset,hint2)||cap==='REFERENCE_SOLUTION'&&sameRef(asset,firstRef)||cap==='BOUNDARY_REFERENCE'&&sameRef(asset,boundaryRef)||cap==='VIEW_STIMULUS'&&sameRef(asset,boundary)||cap==='SOURCE_RETURN'&&sameRef(asset,origin)),boundaryAllowed:async(_j,x)=>sameRef(x,boundary)};
 const controller=new CognitiveController({journey:key,sessionId:as.id,originSessionId:os.id},store,driver,authority);
 const binding={controller,driver,progress,engine,definitionSha256:await transferDefinitionDigest(definition),boundarySessionId:bs.id,assessmentA:assessments[0],assessmentB:assessments[1],loadProtected:async(a:Ref)=>Uint8Array.from(bytes.get(a.id)??[])};
 const make=()=>new Core1BTransferJourney(definition,binding);
 return {driver,store,controller,progress,binding,definition,make,os,as,bs,first,firstRef,boundaryRef,key,bytes,setEnabled:(v:boolean)=>{enabled=v;}};
}
export async function throughFirst(j:Core1BTransferJourney){await j.start();await j.predict(0);j.setResponses(firstResponses,[artifact('work:first')]);await j.saveDraft();await j.commitFirstAttempt();}
export async function throughRepair(j:Core1BTransferJourney){await j.completeReconstruction({'move:one':{observation:'compare first'},'move:two':{observation:'compare second'}});await j.commitDiagnosis('UNSURE','Need to check this move');await j.commitRepair('Repair reasoning',[artifact('work:repair','separate repair')]);}
